F3 = [['etcd key', 'mod_revision 4863'], ['metadata.resourceVersion', '4863'], ['同样的修改再来一次', 'rv 不变'], ['新对象', '更大的 rv']]
F4 = [['rv = 创建时的 4859', 'Exact → 旧内容'], ['rv = 1', 'Expired'], ['rv = 当前 + 100 万', '等 43 秒 → Timeout'], ['rv = 0', '任意版本,可走缓存']]
PANELS = [('f', 'flow', '读写与版本'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("A 和 B 都读到 cm1(resourceVersion=4859),A 先 replace 成功(resourceVersion 变成 4860),B 带着 4859 再 replace:退出码 1,Error from server (Conflict): Operation cannot be fulfilled on configmaps \"cm1\": the object has been modified; please apply your changes to the latest version and try again。cm1 的内容是 A 写的 {\"owner\":\"A\"},B 的修改没有写进去。", f=fl(F1, cur=[2], mark=[3], done=[0, 1]), t=tl(S(1), mark=lidx(S(1), '(Conflict)'), done=lidx(S(1), '写入者 A', 'B 的修改没有写进去')), kv=KV([['replace 带着读到的 resourceVersion', '服务端比对,不一致就拒绝'], ['409 Conflict', 'the object has been modified'], ['处理办法', '重新读、重新改、再提交']], ['409 Conflict'])),
    step("哪些写法会冲突:merge patch 里带着旧的 resourceVersion=4859 → Conflict;merge patch 不带 resourceVersion → 成功,直接覆盖(owner 变成 D);replace 的 YAML 去掉 resourceVersion → 成功(ConfigMap 允许无条件更新,owner 变成 E);kubectl apply 自己读最新的再算 patch、不带 resourceVersion → 没有冲突(owner 变成 F)。", f=fl(F2, cur=[0], mark=[1, 2], done=[3]), t=tl(S(2), mark=lidx(S(2), '退出码 1'), done=lidx(S(2), '退出码 0')), kv=KV([['带 rv', '乐观并发:冲突就失败'], ['不带 rv', '最后写入者获胜'], ['apply / patch', '默认不带 rv,不会因为别人改过而失败']], ['不带 rv'])),
    step("cm1:metadata.resourceVersion=4863,etcd 里这个 key 的 mod_revision 也是 4863,create_revision=4859 正是创建时的 resourceVersion。打标签 x=1 使 4863 → 4864;再打一次一模一样的 x=1 显示 not labeled,仍是 4864;改成 x=2 变成 4865;之后创建 cm2、cm3 得到 4866、4867——所有对象共用 etcd 的一个递增序列。", f=fl(F3, cur=[1], mark=[2], done=[0, 3]), t=tl(S(3), mark=lidx(S(3), 'mod_revision=4863', '没有变化'), done=lidx(S(3), '改成 x=2', '之后创建')), kv=KV([['resourceVersion', '= etcd 里该 key 最后一次修改的 revision'], ['没有实际改动', '不写 etcd,rv 不变'], ['所有对象', '共享同一个递增序列']], ['resourceVersion'])),
    step("按 resourceVersion 读:list?resourceVersion=4859&resourceVersionMatch=Exact 读到 cm1 创建时的内容 {'owner': 'nobody'}(现在是 {\"owner\":\"F\"});resourceVersion=1 的 Exact 读 → Expired: The resourceVersion for the provided list is too old;resourceVersion 比当前大 100 万 → 43.1 秒后返回 Timeout: Too large resource version: 1004868, current: 4936;resourceVersion=0 → 允许任意版本,返回 4 个对象。", f=fl(F4, cur=[0], mark=[1, 2], done=[3]), t=tl(S(4), mark=lidx(S(4), 'Expired', 'Too large resource version'), done=lidx(S(4), 'Exact(cm1 创建时的版本)', 'resourceVersion=0')), kv=KV([['Exact', '读到过去某个 revision 的状态'], ['太旧', 'Expired(etcd 已压缩)'], ['比当前还新', '等不到就 Timeout']], ['Exact'])),
]
A = mkartk('k6', 6, 'Kubernetes,resourceVersion,乐观并发,409 Conflict,etcd revision,真实验证,动画演示',
    '在 kind 集群里实测 resourceVersion:两个写入者读到同一版本后先后 replace,后者得到 409 Conflict;merge patch 带旧 resourceVersion 会冲突、不带就覆盖,kubectl apply 不带 resourceVersion;resourceVersion 等于 etcd 里该 key 的 mod_revision,重复的无实际改动不会让它变化;resourceVersionMatch=Exact 能读回创建时的旧内容,太旧报 Expired,比当前大 100 万的版本等 43.1 秒后报 Too large resource version。',
    '409 Conflict 是 Kubernetes 最常见的并发报错之一,它背后的 resourceVersion 到底是什么?这篇让两个写入者真的互相冲突一次,再对照 etcd 里的 revision,并用 resourceVersion 参数读过去和未来的状态。',
    [('409 Conflict', '带着旧的 resourceVersion=4859 写回时的结果:the object has been modified'), ('4863 = 4863', '对象的 resourceVersion 与 etcd 里该 key 的 mod_revision 完全相同'), ('43.1 秒', '读一个比当前大 100 万的 resourceVersion,apiserver 等了这么久才返回 Timeout')],
    [('谁后写谁冲突', '<p>A 和 B 同时读到 <code>cm1</code>(<code>resourceVersion=4859</code>),A 先 <code>replace</code> 成功,<code>resourceVersion</code> 变成 4860。B 再带着 4859 写回:<code>Conflict … the object has been modified; please apply your changes to the latest version and try again</code>,<code>cm1</code> 里留下的是 A 写的内容。这就是乐观并发:不加锁,提交时比对版本,版本不一致就让你重新读、重新改。</p>'),
     ('什么情况下不会冲突', '<p>冲突只发生在请求里带了 <code>resourceVersion</code> 的时候。merge patch 里带旧版本会冲突,不带就直接覆盖(最后写入者获胜);<code>replace</code> 的 YAML 里去掉 <code>resourceVersion</code>,ConfigMap 允许这样无条件更新;<code>kubectl apply</code> 自己先读最新对象再算 patch,不带 <code>resourceVersion</code>,所以不会因为别人改过而失败——它的风险是悄悄覆盖别人的修改(字段所有权下一篇说)。</p>'),
     ('resourceVersion 是什么', '<p>它就是 etcd 里这个 key 最后一次修改的 revision:<code>cm1</code> 的 <code>resourceVersion</code> 是 4863,etcd 里同一个 key 的 <code>mod_revision</code> 也是 4863,<code>create_revision</code> 4859 就是创建时的版本。所有对象共用 etcd 的同一个递增序列(创建 cm2、cm3 得到 4866、4867)。没有实际改动的更新(重复打同一个标签)不会写 etcd,版本不变。官方把它定义为不透明字符串,不要自己解析或做算术,这里只是观察。</p>'),
     ('按版本读', '<p><code>resourceVersionMatch=Exact</code> 配合创建时的版本,读回了 <code>cm1</code> 创建时的内容(<code>owner: nobody</code>),相当于读到过去;版本太旧(etcd 已压缩)返回 <code>Expired</code>;读一个比当前大得多的版本,apiserver 会等它出现,这次等了 43.1 秒才返回 <code>Timeout: Too large resource version</code>;<code>resourceVersion=0</code> 表示任意版本都行,可以走缓存。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);所有对象都是 k6 命名空间里的 ConfigMap;两个写入者用同一份 kubectl get -o yaml 的结果模拟,A、B 各自 kubectl replace;mod_revision 与 create_revision 用 etcd 静态 Pod 里的 etcdctl get -w json 读出;按版本读用 kubectl get --raw 加 resourceVersion / resourceVersionMatch 参数;每种情形各一次,版本号每次运行不同',
     '没有验证:Pod 等不允许无条件更新的资源(缺 resourceVersion 时的行为);watch 时的 resourceVersion 语义(下一篇);etcd 压缩的具体周期;future 版本等待 43.1 秒的具体来源(只观察到结果);分页 list(limit/continue)时 resourceVersion 的一致性;客户端 retry.RetryOnConflict 的写法'],
    'resourceVersion', PANELS)
